import { Edit2, Trash2 } from '@hexa-ui/icons';
import React from 'react';
import { IconButton } from '../../../icon-button';
import { IconButtonsContainer } from './IconButtons.styles';

interface IconButtonsProps {
  variant?: 'image';
  handleOnClean: (event: React.MouseEvent<HTMLButtonElement>) => void;
  elevation?: boolean;
}

export const IconButtons = ({ variant, handleOnClean, elevation = false }: IconButtonsProps) => (
  <IconButtonsContainer type={variant}>
    <IconButton
      variant="secondary"
      icon={Trash2}
      onClick={handleOnClean}
      style={{ marginRight: '16px' }}
      elevation={elevation}
      aria-label="Delete and clear"
    />
    <IconButton
      type="button"
      variant="secondary"
      icon={Edit2}
      elevation={elevation}
      aria-label="Edit"
    />
  </IconButtonsContainer>
);
